-- the displayed total and the Cox status, before anything moves
CREATE TEMP TABLE _before ON COMMIT DROP AS
SELECT (SELECT COALESCE(sum(a.total_amount), 0) FROM transparent_motivations.contribution_summary_agg a
          JOIN transparent_motivations.politician_sources ps ON ps.id = a.politician_source_id
         WHERE ps.research_status = 'confirmed') AS confirmed_total,
       (SELECT research_status FROM transparent_motivations.politician_sources WHERE id = '852ba953-b38b-49f1-bbe2-82ca9c089280') AS cox_status;


-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM _link;
  IF v_n <> 327 THEN RAISE EXCEPTION 'PRE: _link holds %, expected 327', v_n; END IF;

  -- the population: exactly the 178 CA_0156 class-B rows, all deactivated placeholders
  SELECT count(*) INTO v_n FROM essentials.politicians p
   WHERE EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%')
     AND NOT p.is_active AND p.source = 'scraped' AND p.data_source LIKE 'https://empowered.vote/school-district/%';
  IF v_n <> 178 THEN RAISE EXCEPTION 'PRE: % CA_0156 class-B placeholder rows, expected 178', v_n; END IF;

  -- each link is the recorded (row, system, committee id, stored committee name), still at its reviewed status
  -- (or already disputed by an earlier run of this file), on one of those rows
  SELECT count(*) INTO v_n FROM _link l
    JOIN transparent_motivations.politician_sources ps ON ps.id = l.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.essentials_politician_id = l.politician_id
     AND ps.source_system = l.source_system AND ps.external_id = l.external_id
     AND COALESCE(split_part(ps.notes, ' | ', 1)::jsonb ->> 'committee_name',
                  split_part(ps.notes, ' | ', 1)::jsonb ->> 'cmt_nm') = l.committee
     AND (ps.research_status = l.prior_status
          OR (ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0174 (2026-09-23)') > 0))
     AND NOT p.is_active
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%');
  IF v_n <> 327 THEN RAISE EXCEPTION 'PRE: % of 327 links match their reviewed record on a CA_0156 class-B row', v_n; END IF;

  -- the review was complete: the only confirmed/needs_research link on those rows outside _link is the kept ROCK link.
  -- A link added since the review fails here instead of being left unreviewed.
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.research_status IN ('confirmed', 'needs_research')
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%')
     AND NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = ps.id)
     AND NOT (ps.source_system = 'cal_access' AND ps.external_id = '1303021' AND ps.research_status = 'needs_research');
  IF v_n <> 0 THEN RAISE EXCEPTION 'PRE: % confirmed/needs_research link(s) on CA_0156 class-B rows were not reviewed', v_n; END IF;
END $$;

-- ─── 1. Dispute the 327 links ─────────────────────────────────────────────────────────────────
UPDATE transparent_motivations.politician_sources ps
   SET research_status = 'disputed',
       notes = CASE WHEN ps.notes IS JSON OBJECT
                    THEN (ps.notes::jsonb || jsonb_build_object('disputed_by', 'CA_0174 (2026-09-23)', 'disputed_reason', l.reason))::text
                    ELSE ps.notes || ' | DISPUTED by CA_0174 (2026-09-23): ' || l.reason END,
       updated_at = now()
  FROM _link l
 WHERE ps.id = l.id AND ps.research_status = l.prior_status;

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_amt numeric;
BEGIN
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN _link l ON l.id = ps.id
   WHERE ps.research_status = 'disputed'
     AND ((ps.notes IS JSON OBJECT AND ps.notes::jsonb ->> 'disputed_by' = 'CA_0174 (2026-09-23)' AND ps.notes::jsonb ->> 'disputed_reason' = l.reason)
          OR right(ps.notes, length(' | DISPUTED by CA_0174 (2026-09-23): ' || l.reason)) = ' | DISPUTED by CA_0174 (2026-09-23): ' || l.reason);
  IF v_n <> 327 THEN RAISE EXCEPTION 'POST: % of 327 links disputed with their reason', v_n; END IF;

  -- no confirmed committee is left on any CA_0156 class-B row, and the one needs_research link left is ROCK
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.research_status = 'confirmed'
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%');
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % confirmed link(s) remain on CA_0156 class-B rows', v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.research_status = 'needs_research'
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%');
  IF v_n <> 1 THEN RAISE EXCEPTION 'POST: % needs_research link(s) on CA_0156 class-B rows, expected 1 (ROCK)', v_n; END IF;

  -- this file never touches not_applicable (1,166 measured 2026-09-23)
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.research_status = 'not_applicable'
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(p.notes, ARRAY[]::text[])) n WHERE n LIKE 'CA_0156 (2026-09-22): NO EVIDENCE%');
  IF v_n <> 1166 THEN RAISE EXCEPTION 'POST: % not_applicable links on CA_0156 class-B rows, expected 1166 (untouched)', v_n; END IF;

  -- the Cox money is no longer attributed, and it is still there
  SELECT count(*) INTO v_n FROM transparent_motivations.contribution_summary_agg a
    JOIN transparent_motivations.politician_sources ps ON ps.id = a.politician_source_id
   WHERE a.politician_source_id = '852ba953-b38b-49f1-bbe2-82ca9c089280' AND ps.research_status = 'confirmed';
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: the Cox aggregate is still reachable as confirmed'; END IF;

  SELECT count(*), COALESCE(sum(amount), 0) INTO v_n, v_amt FROM transparent_motivations.contributions
   WHERE politician_source_id = '852ba953-b38b-49f1-bbe2-82ca9c089280';
  IF v_n <> 4 OR v_amt <> 6761.00 THEN RAISE EXCEPTION 'POST: % contributions / % on the Cox source, expected 4 / 6761.00 (untouched)', v_n, v_amt; END IF;

  -- exactly the Cox $6,761.00 left the confirmed total (0 on a re-run)
  SELECT b.confirmed_total - (SELECT COALESCE(sum(a.total_amount), 0) FROM transparent_motivations.contribution_summary_agg a
                               JOIN transparent_motivations.politician_sources ps ON ps.id = a.politician_source_id
                              WHERE ps.research_status = 'confirmed')
    INTO v_amt FROM _before b;
  IF v_amt <> (SELECT CASE WHEN cox_status = 'confirmed' THEN 6761.00 ELSE 0 END FROM _before) THEN
    RAISE EXCEPTION 'POST: the confirmed total moved by %, expected only the Cox 6761.00', v_amt;
  END IF;

  RAISE NOTICE 'CA_0174 applied: 327 wrong committee links disputed on CA_0156 class-B rows; ROCK kept; Cox 6,761.00 no longer attributed';
END $$;

COMMIT;
